// Parse and validate the AI answer. Anything unexpected goes to human review.
const input = $input.first().json;
const originalData = $('Rule Screen (safety + patient data)').first().json;

const CATEGORIES = ['Test ordering', 'Specimen logistics', 'Scientific information',
  'Access and reimbursement', 'Educational resource', 'Safety or medical', 'Other'];
const PRIORITIES = ['Low', 'Medium', 'High'];
const MIN_CONFIDENCE = 0.7;

function getText(j) {
  return j.output?.[0]?.content?.[0]?.text ?? j.message?.content ?? j.text ?? j.content;
}

try {
  const rawText = getText(input);
  if (typeof rawText !== 'string' || !rawText.trim()) {
    throw new Error('AI response is missing or empty');
  }
  const cleanText = rawText.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
  const ai = JSON.parse(cleanText);

  if (!ai || typeof ai !== 'object' || Array.isArray(ai)) throw new Error('AI response must be a JSON object');
  if (typeof ai.human_review_required !== 'boolean') throw new Error('human_review_required must be true or false');
  if (!CATEGORIES.includes(ai.category)) throw new Error('Unknown category: ' + ai.category);
  if (!PRIORITIES.includes(ai.priority)) throw new Error('Unknown priority: ' + ai.priority);
  const confidence = Number(ai.confidence);
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error('confidence must be between 0 and 1');

  const lowConfidence = confidence < MIN_CONFIDENCE;
  return [{
    json: {
      ...originalData,
      category: ai.category,
      priority: ai.priority,
      confidence,
      ai_reason: String(ai.reason || ''),
      human_review_required: ai.human_review_required || lowConfidence,
      low_confidence: lowConfidence,
      ai_output_valid: true,
      ai_output_error: ''
    }
  }];
} catch (error) {
  return [{
    json: {
      ...originalData,
      ai_output_valid: false,
      ai_output_error: error.message,
      human_review_required: true
    }
  }];
}

