// Pick approved content: specialty + topic first, then specialty, then 'All'.
const hcp = $('Prepare CRM Follow-up').first().json;
const rows = $input.all().map(item => item.json);
const normalize = v => String(v ?? '').trim().toLowerCase();

const usableRows = rows.filter(row =>
  String(row['Content Title'] ?? '').trim() &&
  /^https?:\/\/\S+$/i.test(String(row['Approved Link'] ?? '').trim())
);

const sameSpecialty = row => normalize(row.Specialty) === normalize(hcp.Specialty);
const sameTopic = row => normalize(row.Topic) === normalize(hcp.category);
const forAll = row => normalize(row.Specialty) === 'all';

const tiers = [
  ['specialty + topic', row => sameSpecialty(row) && sameTopic(row)],
  ['specialty', sameSpecialty],
  ['all specialties + topic', row => forAll(row) && sameTopic(row)],
  ['all specialties', forAll]
];

let content = null, level = 'none';
for (const [name, test] of tiers) {
  content = usableRows.find(test);
  if (content) { level = name; break; }
}

return [{
  json: {
    ...hcp,
    approved_content_found: Boolean(content),
    content_match_level: level,
    approved_content_title: content?.['Content Title'] || '',
    approved_content_link: String(content?.['Approved Link'] ?? '').trim(),
    approved_content_type: content?.['Content Type'] || '',
    approved_content_topic: content?.Topic || '',
    content_review_reason: content ? '' : `No usable approved content found for specialty: ${hcp.Specialty}`
  }
}];

// Shared by all three email nodes: record which email failed and for whom.
const tryNode = name => { try { return $(name).first().json; } catch (e) { return null; } };
const source = tryNode('Create Medical Review Queue') || tryNode('HCP Enquiry CRM Log') || {};
const err = $input.first().json.error;
return [{
  json: {
    submission_id: source.submission_id || '',
    'HCP Name': source['HCP Name'] || '',
    Email: source.Email || '',
    workflow_status: 'EMAIL_FAILED',
    failure_step: $prevNode.name,
    next_best_action: 'Manually contact the HCP after checking the email failure',
    error_message: (err && (err.message || String(err))) || 'Email failed; inspect execution details'
  }
}];

