// Rule screen: runs BEFORE the AI. Flags safety / off-label topics and
// anything that looks like patient-identifiable information.
const item = $input.first().json;
const text = String(item['HCP Query'] || '');

const SAFETY_TERMS = [
  'adverse event', 'adverse reaction', 'side effect', 'serious reaction',
  'toxicity', 'hospitali[sz]ed', 'death', 'died', 'fatal', 'overdose',
  'pregnan', 'off[- ]?label', 'unapproved use', 'contraindicat',
  'product complaint', 'recall'
];
const PATIENT_DATA_PATTERNS = [
  'patient name', 'date of birth', 'd\\.?o\\.?b\\b', 'mrn\\b',
  'medical record', 'aadhaar', '\\d{1,3}[- ]?(year|yr)s?[- ]old', '\\d{10}\\b'
];
// Titles before a capitalised name (case-sensitive, so "MS Word" is not flagged)
const NAME_TITLE = /\b(Mr|Mrs|Ms|Miss)\.?\s+[A-Z][a-z]+/;

const found = list => list
  .map(t => (text.match(new RegExp('\\b' + t, 'i')) || [])[0])
  .filter(Boolean);
const safety = found(SAFETY_TERMS);
const patient = found(PATIENT_DATA_PATTERNS);
const title = text.match(NAME_TITLE);
if (title) patient.push(title[0]);

const reasons = [];
if (safety.length) reasons.push('Possible safety or off-label enquiry');
if (patient.length) reasons.push('Possible patient-identifiable information in the query');

return [{
  json: {
    ...item,
    rule_flagged: safety.length > 0 || patient.length > 0,
    safety_terms_found: safety,
    phi_suspected: patient.length > 0,
    patient_data_found: patient.length ? '[redacted: ' + patient.length + ' match(es)]' : '',
    screen_reason: reasons.join('; ')
  }
}];

// The OpenAI call failed even after retries: keep the enquiry and send it to a person.
const original = $('Rule Screen (safety + patient data)').first().json;
const err = $input.first().json.error;
const message = (err && (err.message || String(err))) || 'unknown error';
return [{
  json: {
    ...original,
    ai_output_valid: false,
    ai_output_error: 'AI call failed: ' + message,
    human_review_required: true
  }
}];
